mapper.select:
SELECT m.moment_id AS momentId, m.moment_title AS momentTitle, m.moment_category AS momentCategory, l.location_name AS locationName, SUBSTRING_INDEX(m.moment_image_urls, ',', 1) AS momentImageUrl, m.moment_content AS momentContent, m.moment_comment_status AS commentEnabled, m.moment_like AS likeCount, m.moment_view AS viewCount, m.created_at AS createdAt, CASE WHEN m.couple_id = #{coupleId} THEN true ELSE false END AS isOurs FROM tb_moment m JOIN tb_location l ON m.location_id = l.location_id WHERE m.moment_status = true AND m.location_id = #{locationId}
AND m.moment_id < #{cursor}
AND m.couple_id = #{coupleId}
AND (m.couple_id IS NULL OR m.couple_id != #{coupleId})
AND m.moment_certified = true
ORDER BY m.moment_like DESC, m.moment_id DESC
ORDER BY m.moment_id DESC
LIMIT #{size}

SELECT EXISTS (
    SELECT 1
      FROM tb_moment
     WHERE moment_id = #{momentId}
       AND moment_status = true
)
